function formatInvoice(customer: Customer, items: Item[]) {
  return [
    'Invoice',
    'Customer: ' + customer.name,
    ...items.map(i => `${i.name}: ${i.price}`)
  ].join('\n')
}

function sendCustomerInvoice(customer: Customer, items: Item[]) {
  sendEmail(customer.email, formatInvoice(customer, items))
}

function sendAdminInvoice(adminEmail: string, customer: Customer, items: Item[]) {
  sendEmail(adminEmail, formatInvoice(customer, items))
}

// Version B
class BaseEmailSender {
  protected buildLines(customer: Customer, items: Item[]) {
    return [
      'Invoice',
      'Customer: ' + customer.name,
      ...items.map(i => `${i.name}: ${i.price}`)
    ]
  }
}

class CustomerSender extends BaseEmailSender {
  send(customer: Customer, items: Item[]) {
    sendEmail(customer.email, this.buildLines(customer, items).join('\n'))
  }
}

class AdminSender extends BaseEmailSender {
  send(adminEmail: string, customer: Customer, items: Item[]) {
    sendEmail(adminEmail, this.buildLines(customer, items).join('\n'))
  }
}
